import moment from "moment";

/**
 * Calcula a prestação usando a fórmula do sistema de amortização francês (Price)
 * 
 * Fórmula: PMT = PV * [i(1+i)^n] / [(1+i)^n - 1]
 * 
 * Onde:
 * - PMT = Valor da prestação (constante)
 * - PV = Valor presente (capital emprestado)
 * - i = Taxa de juros por período (em decimal, ex: 0.05 para 5%)
 * - n = Número de períodos (prestações)
 * 
 * Características do Sistema Francês:
 * - Todas as prestações têm o mesmo valor
 * - Os juros são calculados sobre o saldo devedor remanescente
 * - A parte de capital aumenta progressivamente
 * - A parte de juros diminui progressivamente
 * 
 * @param {number} principal - Valor do empréstimo (capital)
 * @param {number} interestRate - Taxa de juros por período (em decimal)
 * @param {number} numberOfPeriods - Número de prestações
 * @returns {number} Valor da prestação constante
 */
const calculateFrenchAmortizationInstallment = (principal, interestRate, numberOfPeriods) => {
  // Caso especial: taxa de juros zero (sem juros)
  if (interestRate === 0) {
    return principal / numberOfPeriods;
  }

  const rate = interestRate;
  // Calcula o numerador: i(1+i)^n
  const numerator = rate * Math.pow(1 + rate, numberOfPeriods);
  // Calcula o denominador: (1+i)^n - 1
  const denominator = Math.pow(1 + rate, numberOfPeriods) - 1;
  // Aplica a fórmula completa
  const installment = principal * (numerator / denominator);

  return installment;
};

/**
 * Gera o plano de amortização completo usando o sistema francês (Price)
 * 
 * Este método implementa o sistema de amortização francesa onde:
 * 1. Calcula o valor constante da prestação usando a fórmula PMT
 * 2. Para cada prestação:
 *    - Calcula os juros sobre o saldo devedor atual
 *    - Calcula a amortização (capital) = prestação - juros
 *    - Atualiza o saldo devedor = saldo anterior - amortização
 * 3. Ajusta a última prestação para garantir saldo zero (arredondamento)
 * 
 * @param {Object} loan - Objeto com os dados do empréstimo
 * @param {number} loan.capital - Valor do capital emprestado
 * @param {number} loan.prestacoes - Número de prestações
 * @param {number} loan.juros - Taxa de juros (em decimal)
 * @returns {Array} Array com o plano de amortização completo
 */
const loanSimulator = (loan) => {
  let loanAmount = parseFloat(loan.capital);
  const numberOfInstallments = parseInt(loan.prestacoes);
  const rate = parseFloat(loan.juros);

  // Validações de entrada
  if (loanAmount <= 0 || numberOfInstallments <= 0 || rate < 0) {
    throw new Error("Valores inválidos para cálculo de amortização");
  }

  const amortizationPlan = [];

  // PASSO 1: Calcula o valor da prestação constante usando a fórmula francesa
  const installment = calculateFrenchAmortizationInstallment(
    loanAmount,
    rate,
    numberOfInstallments
  );

  // PASSO 2: Inicializa o saldo devedor com o valor total do empréstimo
  let remainingBalance = loanAmount;

  // PASSO 3: Gera cada prestação do plano
  for (let index = 0; index < numberOfInstallments; index++) {
    // Todas as prestações são mensais
    const dueDate = moment().add(index + 1, "M");

    // Calcula os juros sobre o saldo devedor atual (característica do sistema francês)
    const rateAmount = remainingBalance * rate;
    
    // Calcula a amortização (capital) da prestação
    // No sistema francês, a amortização aumenta progressivamente
    const capitalPerInstall = installment - rateAmount;
    
    // Atualiza o saldo devedor após o pagamento desta prestação
    remainingBalance = remainingBalance - capitalPerInstall;

    // PASSO 4: Ajuste de arredondamento na última prestação
    // Garante que o saldo final seja exatamente zero
    if (index === numberOfInstallments - 1) {
      const adjustment = remainingBalance;
      remainingBalance = 0;

      amortizationPlan.push({
        installmentOrder: (index + 1) + "ª",
        capitalPerInstall: Math.round((capitalPerInstall + adjustment) * 100) / 100,
        rateAmount: Math.round(rateAmount * 100) / 100,
        installment: Math.round((installment + adjustment) * 100) / 100,
        remainingBalance: 0, // Saldo final sempre zero
        dueDate,
      });
    } else {
      amortizationPlan.push({
        installmentOrder: (index + 1) + "ª",
        capitalPerInstall: Math.round(capitalPerInstall * 100) / 100,
        rateAmount: Math.round(rateAmount * 100) / 100,
        installment: Math.round(installment * 100) / 100,
        remainingBalance: Math.round(remainingBalance * 100) / 100,
        dueDate,
      });
    }
  }
  
  return amortizationPlan;
};

export default loanSimulator;
