  created() {
    this.loadAccounts();
  },

  watch: {
    // Recarrega accounts quando a empresa fica disponível
    company(newVal) {
      if (newVal && newVal.id && (!this.accounts || this.accounts.length === 0)) {
        this.loadAccounts();
      }
    },
  },

  computed: {
    ...mapGetters([
      "isLoading",
