  methods: {
    loadAccounts() {
      if (this.company && this.company.id) {
        this.$store.dispatch("getAllAccounts", this.company.id).catch((err) => {
          console.error("Erro ao carregar contas de pagamento:", err);
        });
      }
    },

    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    convertGender() {
      return this.currentCustomer.sex == "M" ? "MUTUÁRIO" : "MUTUÁRIA";
    },

    convertA() {
      return this.currentCustomer.sex == "M" ? "o" : "a";
    },

    /**
     * Calcula o total a pagar (capital + juros) usando a fórmula do sistema francês (Price)
     * Total = PMT * n, onde PMT = PV * [i(1+i)^n] / [(1+i)^n - 1]
     */
    totalAmount(loan) {
      const principal = parseFloat(loan.amount) || 0;
      const rate = parseFloat(loan.interestRate) || 0;
      const n = parseInt(loan.numberOfInstallments) || 1;

      if (principal <= 0) return 0;

      // Sem juros: total = capital
      if (rate === 0) return principal;

      // Fórmula Price: PMT = PV * [i(1+i)^n] / [(1+i)^n - 1]
      const factor = Math.pow(1 + rate, n);
      const installment = principal * (rate * factor) / (factor - 1);
      const total = installment * n;

      return Math.round(total * 100) / 100;
    },

    checkElegibility(loan) {
      const total = this.totalAmount(loan);
      return this.totalGuaranteeAmount >= total;
    },

    openGuaranteesSlide() {
      this.$refs["show-guarantees"].show();
    },

    deleteLoan(loan) {
      this.loanId = loan.id;
      this.$refs["delete-loan"].show();
    },

    deleteGuarantee(id) {
      this.guaranteeId = id;
      this.$refs["delete-guarantee"].show();
    },

    getLoanStatus(status) {
      if (status == 0) {
        return "Em processamento";
      } else if (status == -1) {
        return "Rejeitado";
      } else if (status == 1) {
        return "Desembolsado";
      } else if (status == 2) {
        return "Saneado";
      } else if (status == 3) {
        return "Terminado";
      }
    },

    getStatusVariant(status) {
      const variants = { '-1': 'danger', 0: 'warning', 1: 'info', 2: 'primary', 3: 'success' };
      return variants[status] || 'secondary';
    },

    getStatusIcon(status) {
      const icons = { '-1': 'x-circle-fill', 0: 'clock-fill', 1: 'cash-coin', 2: 'arrow-repeat', 3: 'check-circle-fill' };
      return icons[status] || 'question-circle';
    },

    cancelDeletion() {
      this.$refs["delete-loan"].hide();
    },

    cancelDeletionGuarantee() {
      this.$refs["delete-guarantee"].hide();
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/loan/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            this.getCustomerLoans();
            this.$refs["delete-loan"].hide();
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.$refs["delete-loan"].hide();
          }
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-loan"].hide();
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    decidedToDeleteGuarantee() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/deleteGuarantee/${this.guaranteeId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            this.getLoanGuarantees(false);
            this.$refs["delete-guarantee"].hide();
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.$refs["delete-guarantee"].hide();
          }
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-guarantee"].hide();
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-guarantee"].hide();
        });
    },

    getCustomerLoans() {
      this.$store.dispatch(
        "getCustomerLoans",
        this.currentCustomer.accountNumber
      );
    },

    previewLoan(loan) {
      this.currentLoan = loan;
      this.getLoanGuarantees(false);
      this.$refs["preview-loan"].show();
    },

    onFileChange(e) {
      this.selectedFile = e.target.files[0];
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    printContrat(loan) {
      const ammortizationPlan = AmmortizationPlan.getAmmortization(
        this.customerLoanAmortization
      );

      const loanGuarantees = AmmortizationPlan.getLoanGuarantees(
        this.loanGuarantees
      );

      let docDefinition = {
        footer: {
