        //     {
        //       text: `
        //         ${this.company.companyAddress}\n
        //         Telefone: +${this.company.companyPhone} | E-mail: ${this.company.companyEmail} | Website: ${this.company.companyWebsite} | NUIT: ${this.company.companyNuit}
        //         `,
        //       fontSize: 7,
        //       alignment: "center",
        //     },
        //   ],
        // },

        content: [
          {
            columns: [
              {
