                `,
                fontSize: 7,
                alignment: "center",
              },
            ],
          },
          {
            text: "CONTRATO DE CONCESSÃO DE EMPRÉSTIMO",
            fontSize: 10,
            alignment: "center",
            bold: true,
          },
          {
            text: "\nEntre:\n\n",
            fontSize: 8,
            bold: true,
          },
          {
            text: {
              alignment: "justify",
              fontSize: 8,
              text: `${this.company.companyName}, uma instituição financeira licenciada pelo Banco de Moçambique, devidamente constituída e registada na Conservatória do Registo Comercial sob Alvará nº 43115/11/01/PS/2021, titular do NUIT 103048273 com sede no distrito de Moamba, província de Maputo (Moçambique),
               na Avenida de Tintsivene, casa Branca, Q. 4, Bairro de Mukhatine, contacto (84) 267 88-69, microcreditombr@gmail.com, doravante designada por Mutuante ou Credora`,
            },
          },
          {
            text: `\n&\n\n`,
            fontSize: 8,
          },
          {
            text: {
              alignment: "justify",
              fontSize: 8,
