    onUploadFile() {
      if (!this.selectedFile) {
        this.showToast(
          "Erro!",
          "warning",
          "Seleccione um documento por favor!"
        );
        return;
      }

      if (!this.form.guaranteeDescription) {
        this.showToast(
          "Erro!",
          "warning",
          "Digite a descrição da garantia por favor!"
        );
        return;
      }
      this.$store.commit("LOADING_STATUS", true);
      const storageRef = firebase
        .storage()
        .ref(
          `/customer/${this.currentCustomer.accountNumber}/${this.selectedFile.name}`
        )
        .put(this.selectedFile);
      storageRef.on(
        `state_changed`,
        (snapshot) => {
          this.uploadValue =
            (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        },
        (err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        },
        () => {
          this.uploadValue = 0;
          storageRef.snapshot.ref.getDownloadURL().then((url) => {
            this.form.guaranteeFileUrl = url;
            this.uploadGuaranteeFile();
          });
        }
      );
    },

    uploadGuaranteeFile() {
      this.$store.commit("LOADING_STATUS", true);
      this.form.loanId = this.currentLoan.id;
      axios
        .post(`/api/createGuarantee`, this.form)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${this.form.guaranteeDescription} avaliado a ${this.convertMoney(
                this.form.purchaseAmount
              )} carregado com sucesso.`,
              "Cadastro de Garantias"
            );
            this.$store.dispatch("addLog", logsParams);
            this.form.guaranteeDescription = "";
            this.form.guaranteeFileUrl = "";
            this.form.selectedFile = "";
            this.form.purchaseAmount = 0;
            this.getLoanGuarantees(false);
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    getLoanGuarantees(print) {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/getLoanGuarantees/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.loanGuarantees = data.result;
            this.totalGuaranteeAmount = this.loanGuarantees.reduce(
              (sum, p) => sum + p.purchaseAmount,
              0
            );
            if (print == true) {
              this.printContrat(this.currentLoan);
            }
          } else {
            this.loanGuarantees = [];
            this.totalGuaranteeAmount = 0;
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    getAmortizationLoans(loan, print) {
      this.currentLoan = loan;
      // alert(print)
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/loan/amortization/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.customerLoanAmortization = data.result;
            this.getLoanGuarantees(print);
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.customerLoanAmortization = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.customerLoanAmortization = [];
        });
    },

    approveLoan() {
      // if (this.dueDate.length > 0) {
      //   const currDate = moment(this.dueDate).format("YYYY-MM-DD HH:mm ss");
      //   console.log(this.dueDate);
      //   return;
      // }
      this.$store.commit("LOADING_STATUS", true);
      const passingValues = {
        companyId: this.company.id,
        accountNumber: this.currentLoan.accountNumber,
        loanId: this.currentLoan.id,
        interestRate: this.currentLoan.interestRate,
        numberOfInstallments: this.currentLoan.numberOfInstallments,
        amount: this.currentLoan.amount,
        dueDate: this.dueDate,
        status: 0,
      };
      axios
        .post(`/api/createInstallmentsLoan`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `Mutuário ${
                this.currentLoan.accountNumber
              } recebeu ${this.convertMoney(this.currentLoan.amount)}`,
              `Desembolso de crédito para conta ${this.currentLoan.accountNumber}`
            );
            this.$store.dispatch("addLog", logsParams);
            this.getCustomerLoans();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    rejectLoan(loan) {
      this.$store.commit("LOADING_STATUS", true);
      const passingValues = {
        status: -1,
      };
      axios
        .put(`/api/loan/${loan.id}`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${
                this.currentLoan.accountNumber
              }. Crédito rejeitado no valor de ${this.convertMoney(
                this.currentLoan.amount
              )} por insuficiência de garantias`,
              `Financiamento rejeitado`
            );
            this.$store.dispatch("addLog", logsParams);
            this.getCustomerLoans();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    getLoanAmortization(loan) {
      this.currentLoan = loan;
      this.$refs["loan-payment"].show();
    },

    closeLoanPayment(loan) {
      this.currentLoan = loan;
      this.$refs["loan-payment"].hide();
    },
  },
};
